		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 59, "<script>\n\t\t(function() {\n\t\t\tconst canvas = document.getElementById('performance-chart');\n\t\t\tconst granularitySelect = document.getElementById('chart-granularity');\n\t\t\tif (!canvas || !window.Chart) return;\n\n\t\t\tconst rawPortfolioData = JSON.parse(canvas.dataset.portfolio || '[]');\n\t\t\tconst rawBenchmarkData = JSON.parse(canvas.dataset.benchmark || '[]');\n\n\t\t\t// Sort data by date to ensure chronological order\n\t\t\tfunction sortByDate(data) {\n\t\t\t\tif (!data || data.length === 0) return data;\n\t\t\t\treturn [...data].sort((a, b) => new Date(a.x) - new Date(b.x));\n\t\t\t}\n\n\t\t\t// Downsample data based on granularity\n\t\t\tfunction downsample(data, granularity) {\n\t\t\t\tif (!data || data.length === 0) return data;\n\n\t\t\t\t// First sort the data chronologically\n\t\t\t\tconst sorted = sortByDate(data);\n\n\t\t\t\tif (granularity === 'daily') return sorted;\n\n\t\t\t\tconst result = [];\n\t\t\t\tlet lastKey = null;\n\n\t\t\t\tfor (const point of sorted) {\n\t\t\t\t\tconst date = new Date(point.x);\n\t\t\t\t\tlet key;\n\n\t\t\t\t\tswitch (granularity) {\n\t\t\t\t\t\tcase 'weekly':\n\t\t\t\t\t\t\t// ISO week calculation\n\t\t\t\t\t\t\tconst thursday = new Date(date);\n\t\t\t\t\t\t\tthursday.setDate(date.getDate() + (4 - (date.getDay() || 7)));\n\t\t\t\t\t\t\tconst yearStart = new Date(thursday.getFullYear(), 0, 1);\n\t\t\t\t\t\t\tconst week = Math.ceil((((thursday - yearStart) / 86400000) + 1) / 7);\n\t\t\t\t\t\t\tkey = thursday.getFullYear() + '-W' + week.toString().padStart(2, '0');\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\tcase 'monthly':\n\t\t\t\t\t\t\tkey = date.getFullYear() + '-' + (date.getMonth() + 1).toString().padStart(2, '0');\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\tcase 'quarterly':\n\t\t\t\t\t\t\tconst quarter = Math.floor(date.getMonth() / 3) + 1;\n\t\t\t\t\t\t\tkey = date.getFullYear() + '-Q' + quarter;\n\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\tdefault:\n\t\t\t\t\t\t\tkey = point.x;\n\t\t\t\t\t}\n\n\t\t\t\t\tif (key !== lastKey) {\n\t\t\t\t\t\tresult.push(point);\n\t\t\t\t\t\tlastKey = key;\n\t\t\t\t\t}\n\t\t\t\t}\n\n\t\t\t\treturn result;\n\t\t\t}\n\n\t\t\t// Get time unit based on granularity\n\t\t\tfunction getTimeUnit(granularity) {\n\t\t\t\tswitch (granularity) {\n\t\t\t\t\tcase 'daily': return 'day';\n\t\t\t\t\tcase 'weekly': return 'week';\n\t\t\t\t\tcase 'monthly': return 'month';\n\t\t\t\t\tcase 'quarterly': return 'quarter';\n\t\t\t\t\tdefault: return 'month';\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tlet chart = null;\n\n\t\t\tfunction createChart(granularity) {\n\t\t\t\tconst portfolioData = downsample(rawPortfolioData, granularity);\n\t\t\t\tconst benchmarkData = downsample(rawBenchmarkData, granularity);\n\n\t\t\t\tconst pointRadius = granularity === 'daily' ? 0 : 3;\n\t\t\t\tconst timeUnit = getTimeUnit(granularity);\n\n\t\t\t\tif (chart) {\n\t\t\t\t\tchart.destroy();\n\t\t\t\t}\n\n\t\t\t\tconst ctx = canvas.getContext('2d');\n\t\t\t\tchart = new Chart(ctx, {\n\t\t\t\t\ttype: 'line',\n\t\t\t\t\tdata: {\n\t\t\t\t\t\tdatasets: [\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tlabel: 'Portfolio',\n\t\t\t\t\t\t\t\tdata: portfolioData,\n\t\t\t\t\t\t\t\tborderColor: '#6419e6',\n\t\t\t\t\t\t\t\tbackgroundColor: 'rgba(100, 25, 230, 0.1)',\n\t\t\t\t\t\t\t\tborderWidth: 2,\n\t\t\t\t\t\t\t\tfill: true,\n\t\t\t\t\t\t\t\ttension: 0.1,\n\t\t\t\t\t\t\t\tpointRadius: pointRadius,\n\t\t\t\t\t\t\t\tpointHoverRadius: 5\n\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tlabel: 'SPY Benchmark',\n\t\t\t\t\t\t\t\tdata: benchmarkData,\n\t\t\t\t\t\t\t\tborderColor: '#d926a9',\n\t\t\t\t\t\t\t\tbackgroundColor: 'transparent',\n\t\t\t\t\t\t\t\tborderWidth: 2,\n\t\t\t\t\t\t\t\tborderDash: [5, 5],\n\t\t\t\t\t\t\t\tfill: false,\n\t\t\t\t\t\t\t\ttension: 0.1,\n\t\t\t\t\t\t\t\tpointRadius: 0\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t]\n\t\t\t\t\t},\n\t\t\t\t\toptions: {\n\t\t\t\t\t\tresponsive: true,\n\t\t\t\t\t\tmaintainAspectRatio: false,\n\t\t\t\t\t\tinteraction: {\n\t\t\t\t\t\t\tintersect: false,\n\t\t\t\t\t\t\tmode: 'index'\n\t\t\t\t\t\t},\n\t\t\t\t\t\tscales: {\n\t\t\t\t\t\t\tx: {\n\t\t\t\t\t\t\t\ttype: 'time',\n\t\t\t\t\t\t\t\ttime: {\n\t\t\t\t\t\t\t\t\tunit: timeUnit,\n\t\t\t\t\t\t\t\t\tdisplayFormats: {\n\t\t\t\t\t\t\t\t\t\tday: 'MMM d, yyyy',\n\t\t\t\t\t\t\t\t\t\tweek: 'MMM d, yyyy',\n\t\t\t\t\t\t\t\t\t\tmonth: 'MMM yyyy',\n\t\t\t\t\t\t\t\t\t\tquarter: 'QQQ yyyy'\n\t\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\t\ttooltipFormat: 'MMM d, yyyy'\n\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\tgrid: { color: 'rgba(255,255,255,0.1)' },\n\t\t\t\t\t\t\t\tticks: {\n\t\t\t\t\t\t\t\t\tcolor: 'rgba(255,255,255,0.7)',\n\t\t\t\t\t\t\t\t\tmaxTicksLimit: 12,\n\t\t\t\t\t\t\t\t\tautoSkip: true\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\ty: {\n\t\t\t\t\t\t\t\tgrid: { color: 'rgba(255,255,255,0.1)' },\n\t\t\t\t\t\t\t\tticks: {\n\t\t\t\t\t\t\t\t\tcolor: 'rgba(255,255,255,0.7)',\n\t\t\t\t\t\t\t\t\tcallback: function(value) {\n\t\t\t\t\t\t\t\t\t\treturn ((value - 1) * 100).toFixed(0) + '%';\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t},\n\t\t\t\t\t\tplugins: {\n\t\t\t\t\t\t\tlegend: {\n\t\t\t\t\t\t\t\tlabels: { color: 'rgba(255,255,255,0.9)' }\n\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\ttooltip: {\n\t\t\t\t\t\t\t\tcallbacks: {\n\t\t\t\t\t\t\t\t\tlabel: function(context) {\n\t\t\t\t\t\t\t\t\t\tconst pct = ((context.parsed.y - 1) * 100).toFixed(1);\n\t\t\t\t\t\t\t\t\t\treturn context.dataset.label + ': ' + (pct >= 0 ? '+' : '') + pct + '%';\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t}\n\n\t\t\t// Initial chart\n\t\t\tcreateChart(granularitySelect ? granularitySelect.value : 'monthly');\n\n\t\t\t// Listen for granularity changes\n\t\t\tif (granularitySelect) {\n\t\t\t\tgranularitySelect.addEventListener('change', function() {\n\t\t\t\t\tcreateChart(this.value);\n\t\t\t\t});\n\t\t\t}\n\t\t})();\n\t</script>")
